##' Print parameter table comparisons to latex or (latex) pdf file
##' @param pars Multiple parameter tables in one object as generated by `NMwork::createParameterTable()`.
##' @param label.pmtables A latex label is needed. Like label.pmtables="tab:myfirsttable".
##' requires the pmtables package to be installed.
##' @import data.table
##' @import pmtables

printParamTableComp = function(pars,label.pmtables) {

  partab <- copy(pars)
  info.source <- NMinfo(partab)
  model <- NULL

  dt.conf <- data.table(
    
  )  

  fixUnder <- function(x)gsub("\\_","\\\\_",x)

  string.caption <- paste0("model: ",fixUnder(model$run),".")


  partab <- addEstFormat(pars=partab,rse.cov=TRUE)
  partab[,CI:=switch(
    "cov",
    cov=tab.CI,
    boot=tab.CI.boot,
    none=""
  )]

  setorder(partab,model,panel,i,j)

  partab1 <- partab[,.(
    model,
    parameter.ltx,
    tab.lab.ltx,
    tab.est.ltx,
    CI,
    panel.label,
    i,
    j
  )]

  pars.w <- partab1 %>%
    pivot_wider(
      id_cols = c(parameter.ltx,tab.lab.ltx,panel.label,i,j),
      names_from = model,
      values_from = tab.est.ltx
    ) %>% as.data.table()

  setnames(
    pars.w,
    old=unique(partab1$model),
    new=paste0(unique(partab1$model),"-e")
  )

  ci.w <- partab1[,.(
    parameter.ltx,
    tab.lab.ltx,
    panel.label,
    model,
    CI
  )] %>%
  pivot_wider(
    id_cols = c(parameter.ltx,tab.lab.ltx,panel.label),
    names_from = model,
    values_from = CI
  ) %>% as.data.table()

  setnames(
    ci.w,
    old=unique(partab1$model),
    new=paste0(unique(partab1$model),"-ci")
  )

  pars.w <- merge(
    pars.w,
    ci.w,
    by = cc(parameter.ltx,tab.lab.ltx,panel.label),
    all.x=TRUE
  )

  col.order <- unlist(lapply(unique(partab1$model), function(m) {
    c(paste0(m,"-e"),paste0(m,"-ci"))
  }))

  setorder(pars.w,panel.label,i,j)
  pars.w <- pars.w[,c(
    "parameter.ltx",
    "tab.lab.ltx",
    "panel.label",
    col.order
  ), with = FALSE]

  pars.ltx =
    pars.w %>%
    st_new() %>%
    st_panel("panel.label") %>%
    st_span_split("-") %>%
    st_center("tab.lab.ltx" = col_ragged(6.5)) %>%
    st_blank("parameter.ltx","tab.lab.ltx") %>%
    st_rename(
      "Estimate (RSE\\%)...[CV\\% or Corr\\%]" = "e",
      "95\\% Confidence...Interval" = "ci"
      ) %>%
    st_noteconf(type="minipage",width=1) %>%
    stable_long(lt_cap_label=label.pmtables)
}